ground: linear-gradient(145deg, #0b2b3f 0%, #1a4a6f 100%);\n\t\tdisplay: flex;\n\t\tjustify-content: center;\n\t\talign-items: center;\n\t\tfont-family: 'Courier New', 'VT323', monospace;\n\t\ttouch-action: manipulation;\n\t}\n\n\t/* main game container - fits both desktop and phone */\n\t.game-container {\n\t\tdisplay: flex;\n\t\tjustify-content: center;\n\t\talign-items: center;\n\t\tpadding: 12px;\n\t\tbox-sizing: border-box;\n\t\twidth: 100%;\n\t\theight: 100vh;\n\t\tmax-height: 100vh;\n\t}\n\n\tcanvas {\n\t\tdisplay: block;\n\t\tmargin: 0 auto;\n\t\tbox-shadow: 0 20px 35px rgba(0, 0, 0, 0.4), 0 0 0 3px #f9e7b3, 0 0 0 6px #6b3e1c;\n\t\tborder-radius: 18px;\n\t\tcursor: pointer;\n\t\tbackground-color: #70c5ce;\n\t\twidth: auto;\n\t\theight: auto;\n\t\tmax-width: 100%;\n\t\tmax-height: 100%;\n\t\tobject-fit: contain;\n\t}\n\n\t/* UI overlay for pause / score & messages */\n\t.info-panel {\n\t\tposition: fixed;\n\t\ttop: 15px;\n\t\tleft: 0;\n\t\tright: 0;\n\t\ttext-align: center;\n\t\tpointer-events: none;\n\t\tz-index: 10;\n\t\tfont-weight: bold;\n\t\ttext-shadow: 2px 2px 0 #00000055;\n\t}\n\n\t.score-board {\n\t\tdisplay: inline-block;\n\t\tbackground: #000000aa;\n\t\tbackdrop-filter: blur(5px);\n\t\tpadding: 8px 20px;\n\t\tborder-radius: 60px;\n\t\tcolor: white;\n\t\tfont-size: 2.2rem;\n\t\tfont-weight: bold;\n\t\tletter-spacing: 2px;\n\t\tfont-family: monospace;\n\t\tborder: 1px solid gold;\n\t}\n\n\t.pause-btn-container {\n\t\tposition: fixed;\n\t\tbottom: 20px;\n\t\tright: 20px;\n\t\tz-index: 20;\n\t\tpointer-events: auto;\n\t}\n\n\t.pause-btn {\n\t\tbackground: #2c2e3e;\n\t\tborder: none;\n\t\tcolor: white;\n\t\tfont-size: 1.6rem;\n\t\tfont-weight: bold;\n\t\tpadding: 12px 22px;\n\t\tborder-radius: 60px;\n\t\tcursor: pointer;\n\t\tfont-family: monospace;\n\t\tbox-shadow: 0 6px 0 #121212;\n\t\ttransition: 0.07s linear;\n\t\ttouch-action: manipulation;\n\t\tbackdrop-filter: blur(4px);\n\t\tbackground: #1e2a32cc;\n\t\tborder: 1px solid #ffd966;\n\t}\n\n\t.pause-btn:active {\n\t\ttransform: translateY(3px);\n\t\tbox-shadow: 0 2px 0 #121212;\n\t}\n\n\t.restart-hint {\n\t\tposition: fixed;\n\t\tbottom: 20px;\n\t\tleft: 20px;\n\t\tbackground: #00000099;\n\t\tbackdrop-filter: blur(4px);\n\t\tpadding: 6px 14px;\n\t\tborder-radius: 40px;\n\t\tcolor: #ddd;\n\t\tfont-size: 0.8rem;\n\t\tfont-family: monospace;\n\t\tpointer-events: none;\n\t\tz-index: 10;\n\t\tfont-weight: bold;\n\t}\n\n\t@media (max-width: 600px) {\n\t\t.score-board {\n\t\t\tfont-size: 1.6rem;\n\t\t\tpadding: 4px 16px;\n\t\t}\n\n\t\t.pause-btn {\n\t\t\tpadding: 8px 16px;\n\t\t\tfont-size: 1.2rem;\n\t\t}\n\n\t\t.restart-hint {\n\t\t\tfont-size: 0.65rem;\n\t\t\tbottom: 12px;\n\t\t\tleft: 12px;\n\t\t}\n\t}\n\n\t/* pause overlay message on canvas (optional but adds clarity) */\n\t.game-status-msg {\n\t\tposition: fixed;\n\t\ttop: 50%;\n\t\tleft: 50%;\n\t\ttransform: translate(-50%, -50%);\n\t\tbackground: #000000cc;\n\t\tbackdrop-filter: blur(12px);\n\t\tpadding: 12px 28px;\n\t\tborder-radius: 60px;\n\t\tcolor: #ffec9f;\n\t\tfont-size: 1.7rem;\n\t\tfont-weight: bold;\n\t\tfont-family: monospace;\n\t\tletter-spacing: 2px;\n\t\tborder: 1px solid gold;\n\t\tpointer-events: none;\n\t\tz-index: 15;\n\t\twhite-space: nowrap;\n\t\ttransition: 0.1s ease;\n\t}\n\n\t@media (max-width: 500px) {\n\t\t.game-status-msg {\n\t\t\tfont-size: 1.2rem;\n\t\t\twhite-space: nowrap;\n\t\t\tpadding: 8px 20px;\n\t\t}\n\t}\n</style>`;\n\tdocument.body.innerHTML = `<div class=\"game-container\">\n\t<canvas id=\"flappyCanvas\" width=\"400\" height=\"600\"></canvas>\n</div>\n<div class=\"info-panel\">\n\t<div class=\"score-board\">SCORE: <span id=\"scoreValue\">0</span></div>\n</div>\n<div class=\"pause-btn-container\">\n\t<button class=\"pause-btn\" id=\"pauseButton\">⏸️ PAUSE</button>\n</div>\n<div class=\"restart-hint\">\n\t🐦 Tap / Click | Space | ↑  —  R restart\n</div>\n<div id=\"statusMessage\" class=\"game-status-msg\" style=\"display: none;\"></div>`;\n\t// ---------- CANVAS ----------\n\tconst canvas = document.getElementById('flappyCanvas');\n\tconst ctx = canvas.getContext('2d');\n\n\t// ---------- GAME DIMENSIONS (fixed logic size) ----------\n\tconst CANVAS_W = 400;\n\tconst CANVAS_H = 600;\n\tcanvas.width = CANVAS_W;\n\tcanvas.height = CANVAS_H;\n\n\t// ---------- GAME PARAMETERS ----------\n\tconst GRAVITY = 0.2;\n\tconst JUMP_POWER = -4.6;\n\tconst PIPE_WIDTH = 52;\n\tconst PIPE_GAP = 130;\n\tconst PIPE_SPACING = 220;   // distance between pipe pairs\n\tconst PIPE_SPEED = 2.2;\n\n\t// Bird settings\n\tconst BIRD_RADIUS = 12;\n\tlet bird = {\n\t\tx: CANVAS_W * 0.3,\n\t\ty: CANVAS_H / 2,\n\t\tvelocity: 0,\n\t\trotation: 0\n\t};\n\n\tlet pipes = [];\n\tlet score = 0;\n\tlet gameRunning = true;      // true = game active, but may be paused\n\tlet gamePaused = false;\n\tlet animationId = null;\n\n\t// frame handling for smooth pause\n\tlet lastTimestamp = 0;\n\n\t// Flag to avoid multiple restart loops\n\tlet isGameOverFlag = false;\n\n\t// ---------- HELPER FUNCTIONS ----------\n\tfunction resetGame() {\n\t\t// reset bird\n\t\tbird.y = CANVAS_H / 2;\n\t\tbird.velocity = 0;\n\t\tbird.rotation = 0;\n\t\tscore = 0;\n\t\tupdateScoreUI();\n\t\t// reset pipes\n\t\tpipes = [];\n\t\tgenerateInitialPipes();\n\t\tgameRunning = true;\n\t\tgamePaused = false;\n\t\tisGameOverFlag = false;\n\t\t// hide any status overlay msg if visible\n\t\tconst statusDiv = document.getElementById('statusMessage');\n\t\tstatusDiv.style.display = 'none';\n\t\t// update pause button text to reflect unpaused state\n\t\tconst pauseBtn = document.getElementById('pauseButton');\n\t\tpauseBtn.innerHTML = '⏸️ PAUSE';\n\t\t// restart animation loop (if needed ensure it's running)\n\t\tif (animationId === null) {\n\t\t\tstartAnimation();\n\t\t}\n\t}\n\n\tfunction generateInitialPipes() {\n\t\t// generate first pipe at X = CANVAS_W + offset\n\t\tlet startX = CANVAS_W + 80;\n\t\tfor (let i = 0; i < 3; i++) {\n\t\t\tlet pipeY = getRandomPipeY();\n\t\t\tpipes.push({\n\t\t\t\tx: startX + i * PIPE_SPACING,\n\t\t\t\twidth: PIPE_WIDTH,\n\t\t\t\ttopHeight: pipeY,\n\t\t\t\tbottomY: pipeY + PIPE_GAP,\n\t\t\t\tcounted: false\n\t\t\t});\n\t\t}\n\t}\n\n\tfunction getRandomPipeY() {\n\t\tconst minTop = 40;\n\t\tconst maxTop = CANVAS_H - PIPE_GAP - 40;\n\t\treturn Math.floor(Math.random() * (maxTop - minTop + 1) + minTop);\n\t}\n\n\tfunction addPipe() {\n\t\tlet newPipeY = getRandomPipeY();\n\t\tpipes.push({\n\t\t\tx: CANVAS_W,\n\t\t\twidth: PIPE_WIDTH,\n\t\t\ttopHeight: newPipeY,\n\t\t\tbottomY: newPipeY + PIPE_GAP,\n\t\t\tcounted: false\n\t\t});\n\t}\n\n\tfunction updatePipesAndScore() {\n\t\t// move pipes left & remove offscreen\n\t\tfor (let i = 0; i < pipes.length; i++) {\n\t\t\tpipes[i].x -= PIPE_SPEED;\n\t\t}\n\t\t// remove offscreen pipes (x + width < 0)\n\t\twhile (pipes.length > 0 && pipes[0].x + pipes[0].width < 0) {\n\t\t\tpipes.shift();\n\t\t}\n\t\t// add new pipes when needed (based on last pipe x)\n\t\tif (pipes.length === 0) {\n\t\t\taddPipe();\n\t\t} else {\n\t\t\tlet lastPipe = pipes[pipes.length - 1];\n\t\t\tif (lastPipe.x + lastPipe.width <= CANVAS_W - PIPE_SPACING) {\n\t\t\t\taddPipe();\n\t\t\t}\n\t\t}\n\n\t\t// collision & score logic (only if game is active and not game over)\n\t\tif (!gameRunning || gamePaused) return;\n\n\t\t// Bird collision with pipes & boundaries\n\t\tconst birdLeft = bird.x - BIRD_RADIUS;\n\t\tconst birdRight = bird.x + BIRD_RADIUS;\n\t\tconst birdTop = bird.y - BIRD_RADIUS;\n\t\tconst birdBottom = bird.y + BIRD_RADIUS;\n\n\t\t// ceiling & floor collision\n\t\tif (bird.y - BIRD_RADIUS <= 0 || bird.y + BIRD_RADIUS >= CANVAS_H) {\n\t\t\tgameOver();\n\t\t\treturn;\n\t\t}\n\n\t\tfor (let pipe of pipes) {\n\t\t\tconst pipeLeft = pipe.x;\n\t\t\tconst pipeRight = pipe.x + pipe.width;\n\t\t\tconst topPipeBottom = pipe.topHeight;\n\t\t\tconst bottomPipeTop = pipe.bottomY;\n\n\t\t\t// check horizontal overlap\n\t\t\tif (birdRight > pipeLeft && birdLeft < pipeRight) {\n\t\t\t\t// check vertical collision with top pipe or bottom pipe\n\t\t\t\tif (birdTop < topPipeBottom || birdBottom > bottomPipeTop) {\n\t\t\t\t\tgameOver();\n\t\t\t\t\treturn;\n\t\t\t\t}\n\t\t\t}\n\n\t\t\t// SCORE: when bird passes the pipe (right side of pipe without counting again)\n\t\t\tif (!pipe.counted && pipe.x + pipe.width < bird.x) {\n\t\t\t\tpipe.counted = true;\n\t\t\t\tscore++;\n\t\t\t\tupdateScoreUI();\n\t\t\t}\n\t\t}\n\t}\n\n\tfunction updateBirdPhysics() {\n\t\tif (!gameRunning || gamePaused) return;\n\t\tbird.velocity += GRAVITY;\n\t\tbird.y += bird.velocity;\n\t\t// apply rotation based on vertical velocity (smooth flappy style)\n\t\tbird.rotation = Math.min(Math.max(bird.velocity * 3, -25), 45);\n\t}\n\n\tfunction jump() {\n\t\tif (!gameRunning) return;    // game over, cannot jump\n\t\tif (gamePaused) return;      // no jump while paused\n\t\tbird.velocity = JUMP_POWER;\n\t\t// tiny angular impulse for fun\n\t\tbird.rotation = -20;\n\t}\n\n\tfunction gameOver() {\n\t\tif (!gameRunning) return;\n\t\tgameRunning = false;\n\t\tisGameOverFlag = true;\n\t\t// show game over message via overlay\n\t\tconst statusDiv = document.getElementById('statusMessage');\n\t\tstatusDiv.innerHTML = '💀 GAME OVER  |  PRESS R 💀';\n\t\tstatusDiv.style.display = 'block';\n\t\t// Automatically hide after 2 sec? but keep visible until restart\n\t\t// update pause button to disabled style? we keep but pressing pause does nothing\n\t}\n\n\tfunction updateScoreUI() {\n\t\tdocument.getElementById('scoreValue').innerText = score;\n\t}\n\n\t// ---------- DRAW EVERYTHING (with pause visual style) ----------\n\tfunction drawBackground() {\n\t\t// sky gradient\n\t\tconst grad = ctx.createLinearGradient(0, 0, 0, CANVAS_H);\n\t\tgrad.addColorStop(0, \"#6ed4ff\");\n\t\tgrad.addColorStop(0.7, \"#48b5e0\");\n\t\tctx.fillStyle = grad;\n\t\tctx.fillRect(0, 0, CANVAS_W, CANVAS_H);\n\t\t// clouds\n\t\tctx.fillStyle = \"#ffffffcc\";\n\t\tctx.beginPath();\n\t\tctx.ellipse(60, 80, 35, 30, 0, 0, Math.PI * 2);\n\t\tctx.ellipse(100, 70, 40, 32, 0, 0, Math.PI * 2);\n\t\tctx.ellipse(140, 85, 30, 28, 0, 0, Math.PI * 2);\n\t\tctx.fill();\n\t\tctx.beginPath();\n\t\tctx.ellipse(310, 130, 45, 35, 0, 0, Math.PI * 2);\n\t\tctx.ellipse(350, 115, 35, 30, 0, 0, Math.PI * 2);\n\t\tctx.ellipse(280, 120, 30, 28, 0, 0, Math.PI * 2);\n\t\tctx.fill();\n\t\t// ground decoration\n\t\tctx.fillStyle = \"#8b5a2b\";\n\t\tctx.fillRect(0, CANVAS_H - 20, CANVAS_W, 20);\n\t\tctx.fillStyle = \"#c98a3e\";\n\t\tfor (let i = 0; i < 12; i++) {\n\t\t\tctx.fillRect(i * 45, CANVAS_H - 24, 18, 8);\n\t\t}\n\t}\n\n\tfunction drawPipes() {\n\t\tfor (let pipe of pipes) {\n\t\t\t// top pipe\n\t\t\tctx.fillStyle = \"#2f6b2f\";\n\t\t\tctx.shadowBlur = 0;\n\t\t\tctx.fillRect(pipe.x, 0, pipe.width, pipe.topHeight);\n\t\t\tctx.fillStyle = \"#1f4f1f\";\n\t\t\tctx.fillRect(pipe.x - 5, pipe.topHeight - 30, pipe.width + 10, 32);\n\t\t\tctx.fillStyle = \"#3e9e3e\";\n\t\t\tctx.fillRect(pipe.x, pipe.topHeight - 25, pipe.width, 28);\n\t\t\t// bottom pipe\n\t\t\tconst bottomPipeStartY = pipe.bottomY;\n\t\t\tconst bottomPipeHeight = CANVAS_H - bottomPipeStartY;\n\t\t\tctx.fillStyle = \"#2f6b2f\";\n\t\t\tctx.fillRect(pipe.x, bottomPipeStartY, pipe.width, bottomPipeHeight);\n\t\t\tctx.fillStyle = \"#1f4f1f\";\n\t\t\tctx.fillRect(pipe.x - 5, bottomPipeStartY, pipe.width + 10, 32);\n\t\t\tctx.fillStyle = \"#3e9e3e\";\n\t\t\tctx.fillRect(pipe.x, bottomPipeStartY + 4, pipe.width, 28);\n\t\t}\n\t\tctx.shadowBlur = 0;\n\t}\n\n\tfunction drawBird() {\n\t\tctx.save();\n\t\tctx.translate(bird.x, bird.y);\n\t\tlet rotRad = bird.rotation * Math.PI / 180;\n\t\tctx.rotate(rotRad);\n\t\t// body\n\t\tctx.shadowBlur = 4;\n\t\tctx.shadowColor = \"rgba(0,0,0,0.3)\";\n\t\tctx.beginPath();\n\t\tctx.ellipse(0, 0, BIRD_RADIUS, BIRD_RADIUS * 0.9, 0, 0, Math.PI * 2);\n\t\tctx.fillStyle = \"#FFD966\";\n\t\tctx.fill();\n\t\tctx.beginPath();\n\t\tctx.ellipse(3, -3, 4, 5, 0, 0, Math.PI * 2);\n\t\tctx.fillStyle = \"#000000\";\n\t\tctx.fill();\n\t\tctx.fillStyle = \"#FFFFFF\";\n\t\tctx.beginPath();\n\t\tctx.arc(4, -4, 1.5, 0, Math.PI * 2);\n\t\tctx.fill();\n\t\t// beak\n\t\tctx.beginPath();\n\t\tctx.moveTo(10, -2);\n\t\tctx.lineTo(16, -1);\n\t\tctx.lineTo(10, 2);\n\t\tctx.fillStyle = \"#E67E22\";\n\t\tctx.fill();\n\t\t// wing\n\t\tctx.beginPath();\n\t\tctx.moveTo(-6, 2);\n\t\tctx.quadraticCurveTo(-2, 8, 5, 5);\n\t\tctx.fillStyle = \"#F39C12\";\n\t\tctx.fill();\n\t\tctx.restore();\n\t}\n\n\tfunction drawScoreOnCanvas() {\n\t\tctx.font = \"bold 32px 'Courier New', monospace\";\n\t\tctx.fillStyle = \"white\";\n\t\tctx.shadowBlur = 0;\n\t\tctx.shadowColor = \"black\";\n\t\tctx.fillText(score, CANVAS_W / 2 - 15, 60);\n\t\tctx.fillStyle = \"#ffd966\";\n\t\tctx.fillText(score, CANVAS_W / 2 - 17, 58);\n\t}\n\n\tfunction drawPausedOverlay() {\n\t\tif (gamePaused && gameRunning) {\n\t\t\tctx.globalAlpha = 0.7;\n\t\t\tctx.fillStyle = \"#0a1a2f\";\n\t\t\tctx.fillRect(0, 0, CANVAS_W, CANVAS_H);\n\t\t\tctx.globalAlpha = 1;\n\t\t\tctx.font = \"bold 28px monospace\";\n\t\t\tctx.fillStyle = \"#FFE484\";\n\t\t\tctx.shadowBlur = 0;\n\t\t\tctx.fillText(\"⏸ PAUSED\", CANVAS_W / 2 - 75, CANVAS_H / 2 - 20);\n\t\t\tctx.font = \"16px monospace\";\n\t\t\tctx.fillStyle = \"#cccccc\";\n\t\t\tctx.fillText(\"Tap / Space to resume\", CANVAS_W / 2 - 95, CANVAS_H / 2 + 30);\n\t\t} else if (!gameRunning && isGameOverFlag) {\n\t\t\t// show game over text on canvas as extra\n\t\t\tctx.globalAlpha = 0.85;\n\t\t\tctx.fillStyle = \"#1f2a2e\";\n\t\t\tctx.fillRect(0, 0, CANVAS_W, CANVAS_H);\n\t\t\tctx.globalAlpha = 1;\n\t\t\tctx.font = \"bold 26px monospace\";\n\t\t\tctx.fillStyle = \"#f3b33d\";\n\t\t\tctx.fillText(\"GAME OVER\", CANVAS_W / 2 - 80, CANVAS_H / 2 - 30);\n\t\t\tctx.font = \"14px monospace\";\n\t\t\tctx.fillStyle = \"#efefef\";\n\t\t\tctx.fillText(\"Press 'R' to restart\", CANVAS_W / 2 - 65, CANVAS_H / 2 + 20);\n\t\t}\n\t}\n\n\tfunction renderFrame() {\n\t\t// clear canvas\n\t\tdrawBackground();\n\t\tdrawPipes();\n\t\tdrawBird();\n\t\tif (!gamePaused && gameRunning) drawScoreOnCanvas();\n\t\telse if (gameRunning && gamePaused) drawScoreOnCanvas(); // show score even paused? add just small\n\t\t// draw pause/gameover overlays on top\n\t\tdrawPausedOverlay();\n\t}\n\n\t// ---------- GAME LOOP ----------\n\tfunction gameUpdate() {\n\t\tif (gameRunning && !gamePaused) {\n\t\t\tupdateBirdPhysics();\n\t\t\tupdatePipesAndScore();\n\t\t}\n\t\trenderFrame();\n\t}\n\n\tlet lastFrameTime = 0;\n\tfunction animate(timestamp) {\n\t\tanimationId = requestAnimationFrame(animate);\n\t\tgameUpdate();\n\t}\n\n\tfunction startAnimation() {\n\t\tif (animationId !== null) return;\n\t\tanimationId = requestAnimationFrame(animate);\n\t}\n\n\t// ---------- PAUSE TOGGLE ----------\n\tfunction togglePause() {\n\t\tif (!gameRunning) {\n\t\t\t// if game is over, we don't pause, but maybe restart via R key only\n\t\t\treturn;\n\t\t}\n\t\tgamePaused = !gamePaused;\n\t\tconst pauseBtn = document.getElementById('pauseButton');\n\t\tconst statusMsgDiv = document.getElementById('statusMessage');\n\t\tif (gamePaused) {\n\t\t\tpauseBtn.innerHTML = '▶️ RESUME';\n\t\t\t// show a floating message also disappear after tap? but rely on canvas overlay\n\t\t\tif (statusMsgDiv.style.display === 'block' && statusMsgDiv.innerHTML.includes('GAME OVER')) { }\n\t\t\telse {\n\t\t\t\t// optional transient message (but not needed)\n\t\t\t}\n\t\t} else {\n\t\t\tpauseBtn.innerHTML = '⏸️ PAUSE';\n\t\t\t// hide any accidental message not game over related\n\t\t\tif (!isGameOverFlag) statusMsgDiv.style.display = 'none';\n\t\t}\n\t}\n\n\t// ---------- EVENT HANDLERS (Keyboard, Tap/Click) ----------\n\tfunction handleJumpOrStart(e) {\n\t\t// For touch/click on canvas (or key press) - jump if game running and not paused and not game over\n\t\tif (!gameRunning && isGameOverFlag) {\n\t\t\t// restart on tap when game over? but we have R key, but for better UX we can allow restart also via tap but we'll keep consistent? We'll let 'R' restart. But \n\t\t\treturn;\n\t\t}\n\t\tif (gameRunning && !gamePaused) {\n\t\t\tjump();\n\t\t\te.preventDefault();\n\t\t} else if (gameRunning && gamePaused) {\n\t\t\t// if paused, tapping canvas / space also resumes (convenience)\n\t\t\tif (gamePaused) {\n\t\t\t\ttogglePause();\n\t\t\t\te.preventDefault();\n\t\t\t}\n\t\t}\n\t}\n\n\tfunction handleRestart(e) {\n\t\tif (e.key === 'r' || e.key === 'R') {\n\t\t\te.preventDefault();\n\t\t\tresetGame();\n\t\t}\n\t}\n\n\tfunction globalKeyDown(e) {\n\t\tconst key = e.key;\n\t\tif (key === ' ' || key === 'ArrowUp' || key === 'Space' || key === 'ArrowUp') {\n\t\t\te.preventDefault();\n\t\t\tif (!gameRunning && isGameOverFlag) {\n\t\t\t\tresetGame();\n\t\t\t} else {\n\t\t\t\tif (gameRunning && gamePaused) {\n\t\t\t\t\ttogglePause();\n\t\t\t\t} else if (gameRunning && !gamePaused) {\n\t\t\t\t\tjump();\n\t\t\t\t}\n\t\t\t}\n\t\t}\n\t\tif (key === 'r' || key === 'R') {\n\t\t\te.preventDefault();\n\t\t\tresetGame();\n\t\t}\n\t\tif (key === 'Escape') {\n\t\t\tif (gameRunning && !isGameOverFlag) {\n\t\t\t\ttogglePause();\n\t\t\t\te.preventDefault();\n\t\t\t}\n\t\t}\n\t}\n\n\t// Touch / mouse click on canvas (jump or resume)\n\tfunction canvasClickHandler(e) {\n\t\te.preventDefault();\n\t\tif (!gameRunning && isGameOverFlag) {\n\t\t\tresetGame();\n\t\t\treturn;\n\t\t}\n\t\tif (gameRunning && gamePaused) {\n\t\t\ttogglePause();\n\t\t} else if (gameRunning && !gamePaused) {\n\t\t\tjump();\n\t\t}\n\t}\n\n\t// Pause button explicit handler\n\tfunction pauseButtonHandler(e) {\n\t\te.stopPropagation();\n\t\tif (!gameRunning && isGameOverFlag) {\n\t\t\t// if game over, pressing pause does nothing but we can reset? no, separate.\n\t\t\treturn;\n\t\t}\n\t\ttogglePause();\n\t}\n\n\t// ---------- INITIAL SETUP ----------\n\tfunction init() {\n\t\tresetGame();   // initial pipes, bird etc\n\t\tstartAnimation();\n\t\t// Event listeners\n\t\twindow.addEventListener('keydown', globalKeyDown);\n\t\tcanvas.addEventListener('click', canvasClickHandler);\n\t\tcanvas.addEventListener('touchstart', (e) => {\n\t\t\te.preventDefault();\n\t\t\tcanvasClickHandler(e);\n\t\t}, { passive: false });\n\t\tconst pauseBtn = document.getElementById('pauseButton');\n\t\tpauseBtn.addEventListener('click', pauseButtonHandler);\n\t\t// ensure mobile tap on canvas does not cause double zoom etc\n\t\tcanvas.addEventListener('contextmenu', (e) => e.preventDefault());\n\t}\n\n\t// extra: ensure game container resizes gracefully, canvas crisp\n\twindow.addEventListener('resize', () => { });\n\tinit();\n})();\naddEventListener(\"signal\", async function(e) {\n\tif (e.detail == 15) await window.availableAPIs.terminate();\n});","44146f2b22746f2b7c123faad1cb82551457240c79d38ecc255fe76b7a5f7aa87b6d86545d6a6b2342252dda6717b6dfd91db90aa0ec2a89845f7cc03ba4e961":"{\"path\":\"system/apps/flappy.js\",\"name\":\"Fkappy\"}","b493a1dd2c466229ba8ffb62b09873880b4522ef4d1f357c8c39858912ed4446dc90cb37202b3a7b98408b998689f747ec362956cf63c46652c004aaa5ce5d83":"{\"path\":\"system/apps/simon.js\",\"name\":\"Simon\"}","b977043da8181be1b8a76da1eb23d80f7ecf1379da6d3cafc8b813d19f01e5c67500d13a04fa597bd7be6dfca6a04df3f4220cfe3a371f956d77f054c3199218":"{\"path\":\"system/apps/snake.js\",\"name\":\"Snake\"}","48e23973dfdee94c470d308b47237c7a42867c5a51af06c9db23500f15937be1df2e42e83bb0a14eefd75a1d09488a378d68e8c145f1b10dc447185266fc1624":"// =====BEGIN MANIFEST=====\n// signer: automaticSigner\n// allow: NONE\n// signature: a87adba1ad83eb2a82c72bf2ced645de83f1ce97f82a5058da08e23215a3aa8a8b4564b304d637e72facf065ad0cbd86a3a254f6cf47672bb3a6cdd50fca0902\n// =====END MANIFEST=====\n(async function() {\n\t// @pcos-app-mode isolatable\n\tawait availableAPIs.windowTitleSet(\"Simon\");\n\t// DOM Translation\n\tdocument.head.innerHTML = `<meta name=\"viewport\" content=\"width=device-width, initial-scale=1.0, user-scalable=no, viewport-fit=cover\">\n<style>\n\t* {\n\t\tbox-sizing: border-box;\n\t\tuser-select: none;\n\t\t-webkit-tap-highlight-color: transparent;\n\t}\n\n\tbody {\n\t\tbackground: linear-gradient(145deg, #1a2a3a 0%, #0f1a24 100%);\n\t\tmin-height: 100vh;\n\t\tdisplay: flex;\n\t\tjustify-content: center;\n\t\talign-items: center;\n\t\tfont-family: 'Segoe UI', 'Poppins', system-ui, -apple-system, 'Roboto', sans-serif;\n\t\tmargin: 0;\n\t\tpadding: 16px;\n\t}\n\n\t/* main card container — fits perfectly on any screen */\n\t.simon-container {\n\t\tbackground: rgba(10, 20, 28, 0.65);\n\t\tbackdrop-filter: blur(3px);\n\t\tborder-radius: 64px;\n\t\tpadding: 20px 16px 28px 16px;\n\t\tbox-shadow: 0 20px 35px rgba(0, 0, 0, 0.4), inset 0 1px 0 rgba(255, 255, 255, 0.1);\n\t}\n\n\t/* main game panel */\n\t.simon-game {\n\t\tmax-width: 520px;\n\t\twidth: 100%;\n\t\tmargin: 0 auto;\n\t\tbackground: #0f1a1f;\n\t\tborder-radius: 56px;\n\t\tpadding: 20px 18px 24px 18px;\n\t\tbox-shadow: inset 0 1px 4px rgba(0, 0, 0, 0.6), 0 12px 28px rgba(0, 0, 0, 0.5);\n\t}\n\n\t/* 2x2 button grid */\n\t.simon-pad {\n\t\tdisplay: grid;\n\t\tgrid-template-columns: 1fr 1fr;\n\t\tgap: 18px;\n\t\tmargin-bottom: 28px;\n\t}\n\n\t.color-btn {\n\t\taspect-ratio: 1 / 1;\n\t\tborder-radius: 32px;\n\t\tborder: none;\n\t\tcursor: pointer;\n\t\ttransition: all 0.05s linear;\n\t\tbox-shadow: 0 8px 0 rgba(0, 0, 0, 0.3), inset 0 2px 4px rgba(255, 255, 255, 0.3);\n\t\twill-change: transform;\n\t\ttouch-action: manipulation;\n\t}\n\n\t.color-btn:active {\n\t\ttransform: scale(0.96);\n\t\tbox-shadow: 0 2px 0 rgba(0, 0, 0, 0.3);\n\t}\n\n\t/* active flash effect */\n\t.active-flash {\n\t\tfilter: brightness(1.3) saturate(1.2);\n\t\ttransform: scale(0.98);\n\t\tbox-shadow: 0 0 14px rgba(255, 255, 200, 0.8);\n\t}\n\n\t/* specific colors */\n\t.green {\n\t\tbackground: radial-gradient(circle at 30% 35%, #2ecc71, #1f8a4c);\n\t\tborder-bottom: 4px solid #0e5a32;\n\t}\n\n\t.red {\n\t\tbackground: radial-gradient(circle at 30% 35%, #e74c3c, #b33a2c);\n\t\tborder-bottom: 4px solid #7e2a1f;\n\t}\n\n\t.yellow {\n\t\tbackground: radial-gradient(circle at 30% 35%, #f1c40f, #d4ac0d);\n\t\tborder-bottom: 4px solid #9a7e0a;\n\t}\n\n\t.blue {\n\t\tbackground: radial-gradient(circle at 30% 35%, #3498db, #1f618d);\n\t\tborder-bottom: 4px solid #124263;\n\t}\n\n\t/* info panel */\n\t.info-panel {\n\t\tbackground: #1e2f38;\n\t\tborder-radius: 60px;\n\t\tpadding: 14px 20px;\n\t\tdisplay: flex;\n\t\tjustify-content: space-between;\n\t\talign-items: baseline;\n\t\tflex-wrap: wrap;\n\t\tgap: 12px;\n\t\tbox-shadow: inset 0 1px 3px rgba(0, 0, 0, 0.5), 0 5px 8px rgba(0, 0, 0, 0.2);\n\t}\n\n\t.score-box {\n\t\tbackground: #0a1217;\n\t\tpadding: 8px 18px;\n\t\tborder-radius: 40px;\n\t\tcolor: #f3f9ff;\n\t\tfont-weight: bold;\n\t\tfont-size: 1.6rem;\n\t\tletter-spacing: 2px;\n\t\tfont-family: monospace;\n\t\tbox-shadow: inset 0 1px 3px #00000055, 0 2px 3px rgba(255, 255, 240, 0.1);\n\t\tmin-width: 90px;\n\t\ttext-align: center;\n\t}\n\n\t.score-label {\n\t\tfont-size: 0.7rem;\n\t\ttext-transform: uppercase;\n\t\tletter-spacing: 2px;\n\t\tfont-weight: 500;\n\t\tdisplay: block;\n\t\tcolor: #89b9cf;\n\t}\n\n\t.status {\n\t\tbackground: #000000aa;\n\t\tbackdrop-filter: blur(8px);\n\t\tpadding: 8px 18px;\n\t\tborder-radius: 40px;\n\t\tfont-weight: bold;\n\t\tfont-size: 1.2rem;\n\t\tcolor: #FFE7C4;\n\t\ttext-shadow: 0 1px 2px black;\n\t\tletter-spacing: 1px;\n\t}\n\n\t.control-buttons {\n\t\tdisplay: flex;\n\t\tgap: 12px;\n\t}\n\n\tbutton.action {\n\t\tbackground: #2c3e44;\n\t\tborder: none;\n\t\tfont-size: 1rem;\n\t\tfont-weight: bold;\n\t\tpadding: 8px 18px;\n\t\tborder-radius: 40px;\n\t\tcolor: #f0f7fc;\n\t\tcursor: pointer;\n\t\ttransition: 0.1s linear;\n\t\tbox-shadow: 0 3px 0 #0f191f;\n\t\tfont-family: inherit;\n\t\ttouch-action: manipulation;\n\t}\n\n\tbutton.action:active {\n\t\ttransform: translateY(2px);\n\t\tbox-shadow: 0 1px 0 #0f191f;\n\t}\n\n\t.strict-led {\n\t\tdisplay: flex;\n\t\talign-items: center;\n\t\tgap: 8px;\n\t\tbackground: #1a2b30;\n\t\tpadding: 4px 12px;\n\t\tborder-radius: 50px;\n\t}\n\n\t.led {\n\t\twidth: 16px;\n\t\theight: 16px;\n\t\tborder-radius: 50%;\n\t\tbackground: #4a0000;\n\t\tbox-shadow: inset 0 1px 2px black, 0 0 2px rgba(0, 0, 0, 0.5);\n\t\ttransition: 0.07s linear;\n\t}\n\n\t.led.active-led {\n\t\tbackground: #ff3a2f;\n\t\tbox-shadow: 0 0 8px #ff5e4a;\n\t}\n\n\t.strict-text {\n\t\tfont-size: 0.7rem;\n\t\tfont-weight: bold;\n\t\tcolor: #bdd4db;\n\t}\n\n\t/* responsive tweaks */\n\t@media (max-width: 480px) {\n\t\t.simon-game {\n\t\t\tpadding: 16px 14px 20px;\n\t\t}\n\n\t\t.simon-pad {\n\t\t\tgap: 14px;\n\t\t}\n\n\t\t.color-btn {\n\t\t\tborder-radius: 24px;\n\t\t}\n\n\t\t.score-box {\n\t\t\tfont-size: 1.3rem;\n\t\t\tpadding: 4px 14px;\n\t\t}\n\n\t\t.status {\n\t\t\tfont-size: 0.9rem;\n\t\t\tpadding: 5px 12px;\n\t\t}\n\n\t\tbutton.action {\n\t\t\tpadding: 6px 14px;\n\t\t\tfont-size: 0.85rem;\n\t\t}\n\n\t\t.info-panel {\n\t\t\tpadding: 12px 14px;\n\t\t}\n\t}\n\n\t@media (max-width: 380px) {\n\t\t.simon-pad {\n\t\t\tgap: 10px;\n\t\t}\n\n\t\t.info-panel {\n\t\t\tflex-direction: column;\n\t\t\talign-items: center;\n\t\t}\n\n\t\t.control-buttons {\n\t\t\twidth: 100%;\n\t\t\tjustify-content: center;\n\t\t}\n\t}\n\n\t/* disable pointer events during cpu turn */\n\t.disable-interaction .color-btn {\n\t\tpointer-events: none;\n\t\tcursor: default;\n\t}\n\n\t/* general state */\n\tbutton:focus-visible {\n\t\toutline: 2px solid gold;\n\t}\n</style>`;\n\tdocument.body.innerHTML = `<div class=\"simon-container\">\n\t<div class=\"simon-game\" id=\"simonGame\">\n\t\t<div class=\"simon-pad\" id=\"buttonPad\">\n\t\t\t<button class=\"color-btn green\" data-color=\"green\" data-sound=\"green\" aria-label=\"Green\"></button>\n\t\t\t<button class=\"color-btn red\" data-color=\"red\" data-sound=\"red\" aria-label=\"Red\"></button>\n\t\t\t<button class=\"color-btn yellow\" data-color=\"yellow\" data-sound=\"yellow\" aria-label=\"Yellow\"></button>\n\t\t\t<button class=\"color-btn blue\" data-color=\"blue\" data-sound=\"blue\" aria-label=\"Blue\"></button>\n\t\t</div>\n\n\t\t<div class=\"info-panel\">\n\t\t\t<div class=\"score-box\">\n\t\t\t\t<span class=\"score-label\">SCORE</span>\n\t\t\t\t<span id=\"scoreValue\">0</span>\n\t\t\t</div>\n\t\t\t<div class=\"status\" id=\"statusText\">● START</div>\n\t\t\t<div class=\"control-buttons\">\n\t\t\t\t<button class=\"action\" id=\"startBtn\">▶ START</button>\n\t\t\t\t<div class=\"strict-led\">\n\t\t\t\t\t<div class=\"led\" id=\"strictLed\"></div>\n\t\t\t\t\t<span class=\"strict-text\">STRICT</span>\n\t\t\t\t\t<button class=\"action\" id=\"strictToggleBtn\" style=\"padding: 4px 12px; background:#1e4a5c;\">⚡</button>\n\t\t\t\t</div>\n\t\t\t</div>\n\t\t</div>\n\t</div>\n</div>`;\n\t// ---------- GAME STATE ----------\n\tlet sequence = [];        // array of colors (strings)\n\tlet playerTurn = false;   // is it player's turn to input?\n\tlet playerIndex = 0;      // next index to match in sequence\n\tlet strictMode = false;\n\tlet gameActive = false;    // if game is running (not game over, not idle)\n\tlet allowInput = false;    // only true when playerTurn && !cpuPlaying && gameActive && not waiting for animation\n\t\n\t// UI elements\n\tconst greenBtn = document.querySelector('[data-color=\"green\"]');\n\tconst redBtn = document.querySelector('[data-color=\"red\"]');\n\tconst yellowBtn = document.querySelector('[data-color=\"yellow\"]');\n\tconst blueBtn = document.querySelector('[data-color=\"blue\"]');\n\tconst allColorBtns = [greenBtn, redBtn, yellowBtn, blueBtn];\n\tconst scoreSpan = document.getElementById('scoreValue');\n\tconst statusDiv = document.getElementById('statusText');\n\tconst startBtn = document.getElementById('startBtn');\n\tconst strictToggleBtn = document.getElementById('strictToggleBtn');\n\tconst strictLed = document.getElementById('strictLed');\n\tconst gameContainer = document.getElementById('simonGame');\n\t\n\t// sound simulation (web audio)\n\tlet audioCtx = null;\n\tconst soundMap = {\n\t  green: 523.25,   // C5\n\t  red: 392.00,     // G4\n\t  yellow: 440.00,  // A4\n\t  blue: 329.63     // E4\n\t};\n\t\n\t// helper to play beep (safe for mobile, creates context on first user click)\n\tfunction playTone(freq, duration = 0.2) {\n\t  // try to init audio context on demand, but only if user interacted (start game or click)\n\t  if (!audioCtx) {\n\t\ttry {\n\t\t  audioCtx = new (window.AudioContext || window.webkitAudioContext)();\n\t\t} catch(e) { return; }\n\t  }\n\t  // suspend/resume handling: context must be resumed after user gesture\n\t  if (audioCtx.state === 'suspended') {\n\t\taudioCtx.resume().then(() => {\n\t\t  playToneInternal(freq, duration);\n\t\t}).catch(e=>console.log(\"audio resume fail\"));\n\t  } else {\n\t\tplayToneInternal(freq, duration);\n\t  }\n\t}\n\t\n\tfunction playToneInternal(freq, duration) {\n\t  if (!audioCtx) return;\n\t  const now = audioCtx.currentTime;\n\t  const osc = audioCtx.createOscillator();\n\t  const gain = audioCtx.createGain();\n\t  osc.connect(gain);\n\t  gain.connect(audioCtx.destination);\n\t  osc.frequency.value = freq;\n\t  gain.gain.setValueAtTime(0.2, now);\n\t  gain.gain.exponentialRampToValueAtTime(0.0001, now + duration);\n\t  osc.start();\n\t  osc.stop(now + duration);\n\t}\n\t\n\t// flash a button visually + play sound\n\tfunction animatePress(color, callback) {\n\t  const btn = getButtonByColor(color);\n\t  if (!btn) return;\n\t  btn.classList.add('active-flash');\n\t  const freq = soundMap[color];\n\t  if (freq) playTone(freq, 0.2);\n\t  setTimeout(() => {\n\t\tbtn.classList.remove('active-flash');\n\t\tif (callback) callback();\n\t  }, 180);\n\t}\n\t\n\tfunction getButtonByColor(color) {\n\t  switch(color) {\n\t\tcase 'green': return greenBtn;\n\t\tcase 'red': return redBtn;\n\t\tcase 'yellow': return yellowBtn;\n\t\tcase 'blue': return blueBtn;\n\t\tdefault: return null;\n\t  }\n\t}\n\t\n\t// update score display based on sequence length\n\tfunction updateScoreUI() {\n\t  scoreSpan.innerText = sequence.length;\n\t}\n\t\n\t// set game status message\n\tfunction setStatus(msg, isError = false) {\n\t  statusDiv.innerHTML = msg;\n\t  if (isError) {\n\t\tsetTimeout(() => {\n\t\t  if (statusDiv.innerHTML === msg && gameActive) {\n\t\t\tif (playerTurn) statusDiv.innerHTML = \"🎵 YOUR TURN\";\n\t\t\telse if (!gameActive) {}\n\t\t\telse statusDiv.innerHTML = \"⚡ SIMON'S TURN\";\n\t\t  }\n\t\t}, 1000);\n\t  }\n\t}\n\t\n\t// Enable/disable clicks on game pad\n\tfunction setInteractive(enable) {\n\t  allowInput = enable && gameActive && playerTurn;\n\t  if (enable && playerTurn && gameActive) {\n\t\tgameContainer.classList.remove('disable-interaction');\n\t  } else {\n\t\tgameContainer.classList.add('disable-interaction');\n\t\tif (!enable) gameContainer.classList.add('disable-interaction');\n\t\telse if (!playerTurn || !gameActive) gameContainer.classList.add('disable-interaction');\n\t  }\n\t  // re-evaluate class: if allowInput true -> remove class; else add\n\t  if (allowInput) {\n\t\tgameContainer.classList.remove('disable-interaction');\n\t  } else {\n\t\tgameContainer.classList.add('disable-interaction');\n\t  }\n\t}\n\t\n\t// Show error and optionally reset or handle strict mode loss\n\tfunction handleMistake() {\n\t  if (!gameActive) return;\n\t  if (strictMode) {\n\t\t// strict: game over, reset everything\n\t\tsetStatus(\"❌ STRICT FAIL — GAME OVER\", true);\n\t\tgameOverReset();\n\t  } else {\n\t\t// non-strict: replay current sequence\n\t\tsetStatus(\"⚠️ WRONG! REPEATING...\", true);\n\t\t// disable player input completely\n\t\tplayerTurn = false;\n\t\tsetInteractive(false);\n\t\t// replay same sequence after short delay\n\t\tsetTimeout(() => {\n\t\t  if (gameActive) {\n\t\t\tplaySequence();\n\t\t  }\n\t\t}, 900);\n\t  }\n\t}\n\t\n\t// full game reset (keep strict mode preference)\n\tfunction gameOverReset() {\n\t  gameActive = false;\n\t  playerTurn = false;\n\t  allowInput = false;\n\t  sequence = [];\n\t  playerIndex = 0;\n\t  updateScoreUI();\n\t  setInteractive(false);\n\t  setStatus(\"💀 GAME OVER · PRESS START\");\n\t  // remove any pending timers (by flag control)\n\t}\n\t\n\t// normal reset but keep game active: start fresh round\n\tfunction resetAndStart() {\n\t  // stop any ongoing animations\n\t  gameActive = false; // disable current actions\n\t  playerTurn = false;\n\t  allowInput = false;\n\t  setInteractive(false);\n\t  sequence = [];\n\t  playerIndex = 0;\n\t  updateScoreUI();\n\t  // restart new game fresh\n\t  startGameLogic();\n\t}\n\t\n\t// begin new game session\n\tfunction startGameLogic() {\n\t  if (!audioCtx) {\n\t\t// init audio on start click, good for mobile\n\t\ttry {\n\t\t  audioCtx = new (window.AudioContext || window.webkitAudioContext)();\n\t\t} catch(e) {}\n\t  }\n\t  // resume audio if suspended\n\t  if (audioCtx && audioCtx.state === 'suspended') {\n\t\taudioCtx.resume();\n\t  }\n\t  gameActive = true;\n\t  sequence = [];\n\t  playerIndex = 0;\n\t  updateScoreUI();\n\t  // add first random color to sequence\n\t  addRandomStep();\n\t  // start showing sequence\n\t  playSequence();\n\t}\n\t\n\t// add one random color to sequence\n\tfunction addRandomStep() {\n\t  const colors = ['green', 'red', 'yellow', 'blue'];\n\t  const randomColor = colors[Math.floor(Math.random() * colors.length)];\n\t  sequence.push(randomColor);\n\t  updateScoreUI();\n\t}\n\t\n\t// plays the entire sequence with delays\n\tfunction playSequence() {\n\t  if (!gameActive) return;\n\t  playerTurn = false;\n\t  setInteractive(false);\n\t  setStatus(\"🎹 SIMON'S TURN\");\n\t  let idx = 0;\n\t  function playNext() {\n\t\tif (!gameActive) return;\n\t\tif (idx >= sequence.length) {\n\t\t  // finished showing sequence -> enable player turn\n\t\t  playerTurn = true;\n\t\t  playerIndex = 0;\n\t\t  setInteractive(true);\n\t\t  setStatus(\"🎵 YOUR TURN\");\n\t\t  return;\n\t\t}\n\t\tconst color = sequence[idx];\n\t\tanimatePress(color, () => {\n\t\t  idx++;\n\t\t  setTimeout(playNext, 280);\n\t\t});\n\t  }\n\t  playNext();\n\t}\n\t\n\t// called when player successfully matches a full round\n\tfunction playerRoundComplete() {\n\t  if (!gameActive) return;\n\t  // check if player finished whole sequence\n\t  if (playerIndex === sequence.length) {\n\t\t// round complete: add next step\n\t\taddRandomStep();\n\t\t// after a short pause, show the new extended sequence\n\t\tplayerTurn = false;\n\t\tsetInteractive(false);\n\t\tsetStatus(\"✅ GOOD! NEXT ROUND\");\n\t\tsetTimeout(() => {\n\t\t  if (gameActive) {\n\t\t\tplaySequence();\n\t\t  }\n\t\t}, 700);\n\t  } else {\n\t\t// still more to press, keep interactive but stay playerTurn true\n\t\tsetInteractive(true);\n\t  }\n\t}\n\t\n\t// player pressed a color button\n\tfunction onPlayerPress(color) {\n\t  if (!gameActive) return;\n\t  if (!playerTurn || !allowInput) return;\n\t  \n\t  // play press feedback\n\t  animatePress(color, null);\n\t  \n\t  const expectedColor = sequence[playerIndex];\n\t  if (color === expectedColor) {\n\t\t// correct press\n\t\tplayerIndex++;\n\t\t// check win condition\n\t\tif (playerIndex === sequence.length) {\n\t\t  // won the round\n\t\t  playerTurn = false;\n\t\t  setInteractive(false);\n\t\t  setStatus(\"🌟 ROUND COMPLETE!\");\n\t\t  // check for max win? we just continue after timeout\n\t\t  setTimeout(() => {\n\t\t\tif (gameActive) {\n\t\t\t  playerRoundComplete();\n\t\t\t}\n\t\t  }, 400);\n\t\t} else {\n\t\t  // just correct, continue, keep player turn active\n\t\t  setInteractive(true);\n\t\t}\n\t  } else {\n\t\t// wrong press\n\t\thandleMistake();\n\t  }\n\t}\n\t\n\t// Strict mode toggle\n\tfunction toggleStrictMode() {\n\t  if (!gameActive) {\n\t\tstrictMode = !strictMode;\n\t\tupdateStrictLed();\n\t\tsetStatus(strictMode ? \"⚡ STRICT MODE ON\" : \"🔵 STRICT MODE OFF\");\n\t  } else {\n\t\t// if game is active, we can still toggle but we show warning / but toggle allowed? classic simon can change anytime\n\t\tstrictMode = !strictMode;\n\t\tupdateStrictLed();\n\t\tsetStatus(strictMode ? \"⚠️ STRICT ENABLED\" : \"🔵 STRICT DISABLED\", false);\n\t\tsetTimeout(() => {\n\t\t  if (gameActive && !playerTurn) setStatus(\"🎹 SIMON'S TURN\");\n\t\t  else if (gameActive && playerTurn) setStatus(\"🎵 YOUR TURN\");\n\t\t}, 1000);\n\t  }\n\t}\n\t\n\tfunction updateStrictLed() {\n\t  if (strictMode) {\n\t\tstrictLed.classList.add('active-led');\n\t  } else {\n\t\tstrictLed.classList.remove('active-led');\n\t  }\n\t}\n\t\n\t// START handler (reset + start)\n\tfunction onStart() {\n\t  // kill any ongoing game loops, fully reset\n\t  if (audioCtx && audioCtx.state === 'suspended') {\n\t\taudioCtx.resume();\n\t  }\n\t  gameActive = false; // halt current async flows\n\t  playerTurn = false;\n\t  allowInput = false;\n\t  setInteractive(false);\n\t  sequence = [];\n\t  playerIndex = 0;\n\t  updateScoreUI();\n\t  // restart fresh\n\t  startGameLogic();\n\t}\n\t\n\t// attach click listeners to color buttons\n\tfunction bindEvents() {\n\t  greenBtn.addEventListener('click', (e) => {\n\t\te.stopPropagation();\n\t\tonPlayerPress('green');\n\t  });\n\t  redBtn.addEventListener('click', (e) => {\n\t\te.stopPropagation();\n\t\tonPlayerPress('red');\n\t  });\n\t  yellowBtn.addEventListener('click', (e) => {\n\t\te.stopPropagation();\n\t\tonPlayerPress('yellow');\n\t  });\n\t  blueBtn.addEventListener('click', (e) => {\n\t\te.stopPropagation();\n\t\tonPlayerPress('blue');\n\t  });\n\t  \n\t  startBtn.addEventListener('click', () => {\n\t\tonStart();\n\t  });\n\t  strictToggleBtn.addEventListener('click', (e) => {\n\t\te.stopPropagation();\n\t\ttoggleStrictMode();\n\t  });\n\t}\n\t\n\t// ensure touch & mouse friendly, prevent double tap zoom on buttons\n\tfunction setupMobileFriendly() {\n\t  allColorBtns.forEach(btn => {\n\t\tbtn.addEventListener('touchstart', (e) => {\n\t\t  // prevent ghost clicks, but keep functionality\n\t\t  e.preventDefault();\n\t\t  btn.click();\n\t\t}, {passive: false});\n\t  });\n\t}\n\t\n\t// initial UI state\n\tfunction initUI() {\n\t  updateScoreUI();\n\t  setStatus(\"⚡ PRESS START\");\n\t  gameActive = false;\n\t  playerTurn = false;\n\t  setInteractive(false);\n\t  updateStrictLed();\n\t  strictMode = false;\n\t  gameContainer.classList.add('disable-interaction');\n\t}\n\t\n\t// preload audio hint (no auto, but we prepare)\n\twindow.addEventListener('load', () => {\n\t  initUI();\n\t  bindEvents();\n\t  setupMobileFriendly();\n\t});\n\t\n\t// ensure that when game is reset by strict fail we don't double fire\n\tfunction onStrictFailReset() {\n\t  // same as gameOverReset but already implemented\n\t}\n\t\n\t// expose optional reset for strict handler\n})();\naddEventListener(\"signal\", async function(e) {\n\tif (e.detail == 15) await window.availableAPIs.terminate();\n});","e01bdf052906426c119772ca2ed5678032767812f1f8d2c078c7ad313acfe82f6ebbaec19ba85d7d089b8582ac7e5248c850662d8b109bbcbdbb47b9fbb112c2":"// =====BEGIN MANIFEST=====\n// signer: automaticSigner\n// allow: NONE\n// signature: eb1a3e8a7794529819d8f1e4cd2eeb9304e43c7c2dbb8440df3cc2c12adab682fb7b0b10756b8de8cf52360faef9e6246cf06561deab701321db3f842a266909\n// =====END MANIFEST=====\n(async function() {\n\t// @pcos-app-mode isolatable\n\tawait availableAPIs.windowTitleSet(\"Snake\");\n\t// DOM Translation\n\tdocument.head.innerHTML = `<meta name=\"viewport\" content=\"width=device-width, initial-scale=1.0, user-scalable=no, viewport-fit=cover\">\n<style>\n\t* {\n\t\tbox-sizing: border-box;\n\t\tuser-select: none;\n\t\t-webkit-tap-highlight-color: transparent;\n\t}\n\n\tbody {\n\t\tbackground: radial-gradient(circle at 20% 30%, #1a472a, #0a1f0e);\n\t\tmin-height: 100vh;\n\t\tdisplay: flex;\n\t\tjustify-content: center;\n\t\talign-items: center;\n\t\tfont-family: 'Segoe UI', 'Courier New', 'Press Start 2P', monospace;\n\t\tmargin: 0;\n\t\tpadding: 16px;\n\t}\n\n\t/* main game card */\n\t.game-container {\n\t\tbackground: #0d2b1a;\n\t\tborder-radius: 48px;\n\t\tpadding: 20px 16px 24px 16px;\n\t\tbox-shadow: 0 20px 35px rgba(0, 0, 0, 0.5), inset 0 1px 2px rgba(255, 255, 255, 0.1);\n\t\ttransition: all 0.2s;\n\t}\n\n\t/* responsive canvas wrapper */\n\t.canvas-wrapper {\n\t\tdisplay: flex;\n\t\tjustify-content: center;\n\t\tmargin: 0 auto;\n\t}\n\n\tcanvas {\n\t\tbackground-color: #1e3a2f;\n\t\tborder-radius: 24px;\n\t\tdisplay: block;\n\t\tbox-shadow: 0 12px 28px rgba(0, 0, 0, 0.5), inset 0 0 0 2px #5f9e6e;\n\t\twidth: min(70vw, 70vh, 540px);\n\t\theight: min(70vw, 70vh, 540px);\n\t\tcursor: pointer;\n\t}\n\n\t/* info panel */\n\t.info-panel {\n\t\tdisplay: flex;\n\t\tjustify-content: space-between;\n\t\talign-items: baseline;\n\t\tmargin: 18px 12px 10px 12px;\n\t\tgap: 18px;\n\t\tflex-wrap: wrap;\n\t}\n\n\t.score-box {\n\t\tbackground: #010d06;\n\t\tpadding: 8px 20px;\n\t\tborder-radius: 60px;\n\t\tbox-shadow: inset 0 2px 5px #00000033, 0 4px 8px rgba(0, 0, 0, 0.3);\n\t}\n\n\t.score-label {\n\t\tfont-size: 0.9rem;\n\t\tletter-spacing: 2px;\n\t\tcolor: #b1e6c7;\n\t\tfont-weight: bold;\n\t\ttext-transform: uppercase;\n\t}\n\n\t.score-value {\n\t\tfont-size: 2rem;\n\t\tfont-weight: 800;\n\t\tcolor: #f9f3b0;\n\t\tline-height: 1;\n\t\ttext-shadow: 0 2px 0 #2f5e3a;\n\t\tfont-family: monospace;\n\t}\n\n\t.status {\n\t\tbackground: #00000066;\n\t\tbackdrop-filter: blur(4px);\n\t\tpadding: 6px 20px;\n\t\tborder-radius: 60px;\n\t\tfont-weight: bold;\n\t\tfont-size: 1rem;\n\t\tcolor: #f3ffcf;\n\t}\n\n\t/* button panel (touch + desktop) */\n\t.controls {\n\t\tdisplay: flex;\n\t\tjustify-content: center;\n\t\tflex-wrap: wrap;\n\t\tgap: 14px;\n\t\tmargin: 20px 8px 8px 8px;\n\t}\n\n\tbutton {\n\t\tbackground: #2b4b35;\n\t\tborder: none;\n\t\tfont-family: inherit;\n\t\tfont-weight: bold;\n\t\tfont-size: 1.25rem;\n\t\tpadding: 10px 18px;\n\t\tmin-width: 70px;\n\t\tborder-radius: 60px;\n\t\tcolor: #efffdf;\n\t\tbox-shadow: 0 5px 0 #0a2b18;\n\t\tcursor: pointer;\n\t\ttransition: 0.07s linear;\n\t\tletter-spacing: 1px;\n\t\tdisplay: inline-flex;\n\t\talign-items: center;\n\t\tjustify-content: center;\n\t\tgap: 8px;\n\t}\n\n\tbutton:active {\n\t\ttransform: translateY(3px);\n\t\tbox-shadow: 0 2px 0 #0a2b18;\n\t}\n\n\t.dir-buttons {\n\t\tdisplay: flex;\n\t\tgap: 12px;\n\t\tbackground: #1c3626b3;\n\t\tpadding: 8px 16px;\n\t\tborder-radius: 80px;\n\t\tbackdrop-filter: blur(2px);\n\t}\n\n\t.dir-btn {\n\t\tbackground: #1f4230;\n\t\tfont-size: 1.6rem;\n\t\tpadding: 6px 18px;\n\t\tmin-width: 70px;\n\t\tfont-weight: bold;\n\t}\n\n\t.action-btn {\n\t\tbackground: #5e3a2c;\n\t\tbox-shadow: 0 5px 0 #3a231a;\n\t}\n\n\t.restart-btn {\n\t\tbackground: #2f6b47;\n\t\tbox-shadow: 0 5px 0 #1a442e;\n\t}\n\n\t.pause-btn {\n\t\tbackground: #6e5c2c;\n\t\tbox-shadow: 0 5px 0 #4a3b1c;\n\t}\n\n\t@media (max-width: 550px) {\n\t\t.game-container {\n\t\t\tpadding: 12px 12px 20px;\n\t\t}\n\n\t\tbutton {\n\t\t\tpadding: 6px 12px;\n\t\t\tfont-size: 1rem;\n\t\t\tmin-width: 58px;\n\t\t}\n\n\t\t.dir-btn {\n\t\t\tfont-size: 1.3rem;\n\t\t\tpadding: 5px 14px;\n\t\t\tmin-width: 58px;\n\t\t}\n\n\t\t.score-value {\n\t\t\tfont-size: 1.6rem;\n\t\t}\n\n\t\t.status {\n\t\t\tfont-size: 0.75rem;\n\t\t\tpadding: 4px 16px;\n\t\t}\n\t}\n\n\t@media (max-width: 420px) {\n\t\t.dir-buttons {\n\t\t\tgap: 6px;\n\t\t}\n\n\t\t.dir-btn {\n\t\t\tmin-width: 52px;\n\t\t\tpadding: 5px 8px;\n\t\t}\n\t}\n\n\tfooter {\n\t\tfont-size: 0.65rem;\n\t\ttext-align: center;\n\t\tcolor: #779b83;\n\t\tmargin-top: 12px;\n\t\tletter-spacing: 1px;\n\t}\n</style>`;\n\tdocument.body.innerHTML = `<div>\n\t<div class=\"game-container\">\n\t\t<div class=\"canvas-wrapper\">\n\t\t\t<canvas id=\"snakeCanvas\" width=\"500\" height=\"500\"></canvas>\n\t\t</div>\n\n\t\t<div class=\"info-panel\">\n\t\t\t<div class=\"score-box\">\n\t\t\t\t<div class=\"score-label\">🍎 SCORE</div>\n\t\t\t\t<div class=\"score-value\" id=\"scoreDisplay\">0</div>\n\t\t\t</div>\n\t\t\t<div class=\"status\" id=\"statusText\">▶ GAME ACTIVE</div>\n\t\t</div>\n\n\t\t<div class=\"controls\">\n\t\t\t<div class=\"dir-buttons\">\n\t\t\t\t<button class=\"dir-btn\" data-dir=\"UP\">▲</button>\n\t\t\t\t<button class=\"dir-btn\" data-dir=\"LEFT\">◀</button>\n\t\t\t\t<button class=\"dir-btn\" data-dir=\"DOWN\">▼</button>\n\t\t\t\t<button class=\"dir-btn\" data-dir=\"RIGHT\">▶</button>\n\t\t\t</div>\n\t\t\t<button class=\"action-btn pause-btn\" id=\"pauseButton\">⏸️ PAUSE</button>\n\t\t\t<button class=\"action-btn restart-btn\" id=\"restartButton\">⟳ RESTART</button>\n\t\t</div>\n\t\t<footer>←  →  ↑  ↓  •  [P] pause  •  [R] restart</footer>\n\t</div>\n</div>`;\n\t// ---------- CONFIGURATION ----------\n\tconst BOARD_SIZE = 20;       // 20x20 grid\n\tconst CELL_SIZE = 500 / BOARD_SIZE; // 25px logical, canvas is 500x500\n\tconst BASE_SPEED_MS = 150;   // milliseconds per tick\n\n\t// DOM elements\n\tconst canvas = document.getElementById('snakeCanvas');\n\tconst ctx = canvas.getContext('2d');\n\tconst scoreSpan = document.getElementById('scoreDisplay');\n\tconst statusDiv = document.getElementById('statusText');\n\n\t// Game state variables\n\tlet snake = [];          // array of [x,y] positions\n\tlet food = { x: 12, y: 12 };\n\tlet direction = 'RIGHT';      // current moving direction\n\tlet nextDirection = 'RIGHT';\n\tlet score = 0;\n\tlet gameActive = true;    // false if game over (lose/win)\n\tlet paused = false;\n\tlet gameInterval = null;\n\tlet winFlag = false;       // to differentiate win/loss message\n\n\t// Helper: check if two positions match\n\tfunction isPosEqual(p1, p2) {\n\t\treturn p1[0] === p2[0] && p1[1] === p2[1];\n\t}\n\n\t// Get random integer in range\n\tfunction randomInt(min, max) {\n\t\treturn Math.floor(Math.random() * (max - min + 1)) + min;\n\t}\n\n\t// Check if a given (x,y) is inside the snake body\n\tfunction isOnSnake(x, y, ignoreHead = false) {\n\t\tfor (let i = (ignoreHead ? 1 : 0); i < snake.length; i++) {\n\t\t\tif (snake[i][0] === x && snake[i][1] === y) return true;\n\t\t}\n\t\treturn false;\n\t}\n\n\t// Get all free cells (empty positions not occupied by snake)\n\tfunction getFreeCells() {\n\t\tconst free = [];\n\t\tfor (let i = 0; i < BOARD_SIZE; i++) {\n\t\t\tfor (let j = 0; j < BOARD_SIZE; j++) {\n\t\t\t\tif (!isOnSnake(i, j, false)) {\n\t\t\t\t\tfree.push([i, j]);\n\t\t\t\t}\n\t\t\t}\n\t\t}\n\t\treturn free;\n\t}\n\n\t// Generate new food at random empty cell, returns true if success, false if no free cells (win)\n\tfunction generateRandomFood() {\n\t\tconst freeCells = getFreeCells();\n\t\tif (freeCells.length === 0) {\n\t\t\treturn false;   // board full -> win condition\n\t\t}\n\t\tconst randomIndex = Math.floor(Math.random() * freeCells.length);\n\t\tconst [fx, fy] = freeCells[randomIndex];\n\t\tfood = { x: fx, y: fy };\n\t\treturn true;\n\t}\n\n\t// Reset game fully (start new game)\n\tfunction resetGame() {\n\t\t// stop ongoing interval\n\t\tif (gameInterval) {\n\t\t\tclearInterval(gameInterval);\n\t\t\tgameInterval = null;\n\t\t}\n\n\t\t// initial snake: length 3 horizontal in the middle\n\t\tconst mid = Math.floor(BOARD_SIZE / 2);\n\t\tsnake = [\n\t\t\t[mid, mid],     // head\n\t\t\t[mid - 1, mid],\n\t\t\t[mid - 2, mid]\n\t\t];\n\t\tdirection = 'RIGHT';\n\t\tnextDirection = 'RIGHT';\n\t\tscore = 0;\n\t\tgameActive = true;\n\t\tpaused = false;\n\t\twinFlag = false;\n\t\tupdateScoreUI();\n\t\tstatusDiv.innerText = '▶ GAME ACTIVE';\n\t\tstatusDiv.style.color = '#f3ffcf';\n\n\t\t// generate first food avoiding snake\n\t\tif (!generateRandomFood()) {\n\t\t\t// edge case: but new board has free space, so safe fallback\n\t\t\tfood = { x: 5, y: 5 };\n\t\t\twhile (isOnSnake(food.x, food.y)) {\n\t\t\t\tfood = { x: randomInt(0, BOARD_SIZE - 1), y: randomInt(0, BOARD_SIZE - 1) };\n\t\t\t}\n\t\t}\n\n\t\tdrawGame();    // immediate fresh draw\n\t\tstartGameLoop();  // start ticker\n\t}\n\n\t// Start/resume interval (only if gameActive and not paused)\n\tfunction startGameLoop() {\n\t\tif (gameInterval) clearInterval(gameInterval);\n\t\tif (gameActive && !paused) {\n\t\t\tgameInterval = setInterval(gameTick, BASE_SPEED_MS);\n\t\t} else {\n\t\t\tgameInterval = null;\n\t\t}\n\t}\n\n\t// stop interval (used during pause or game over)\n\tfunction stopGameLoop() {\n\t\tif (gameInterval) {\n\t\t\tclearInterval(gameInterval);\n\t\t\tgameInterval = null;\n\t\t}\n\t}\n\n\t// Toggle pause state (only if game is active, not game over)\n\tfunction togglePause() {\n\t\tif (!gameActive) return;   // cannot pause when game over\n\n\t\tpaused = !paused;\n\t\tif (paused) {\n\t\t\t// pause the game\n\t\t\tstopGameLoop();\n\t\t\tstatusDiv.innerText = '⏸ PAUSED';\n\t\t\tstatusDiv.style.color = '#eacd8a';\n\t\t\tdrawGame();  // redraw with pause overlay\n\t\t} else {\n\t\t\t// resume\n\t\t\tstatusDiv.innerText = '▶ GAME ACTIVE';\n\t\t\tstatusDiv.style.color = '#f3ffcf';\n\t\t\tstartGameLoop();\n\t\t\tdrawGame();  // remove overlay text\n\t\t}\n\t}\n\n\t// Update score display\n\tfunction updateScoreUI() {\n\t\tscoreSpan.innerText = score;\n\t}\n\n\t// Handle game over (loss or win)\n\tfunction endGame(isWin = false) {\n\t\tif (!gameActive) return;\n\t\tgameActive = false;\n\t\twinFlag = isWin;\n\t\tstopGameLoop();\n\t\tif (isWin) {\n\t\t\tstatusDiv.innerText = '🏆 YOU WIN! 🏆';\n\t\t\tstatusDiv.style.color = '#ffd966';\n\t\t} else {\n\t\t\tstatusDiv.innerText = '💀 GAME OVER 💀';\n\t\t\tstatusDiv.style.color = '#f5ac78';\n\t\t}\n\t\tdrawGame(); // draw final frame with game over message\n\t}\n\n\t// Core movement logic\n\tfunction moveSnake() {\n\t\tif (!gameActive || paused) return false; // movement only when active & not paused\n\n\t\t// commit queued direction if not opposite\n\t\tconst oppositeMap = {\n\t\t\t'UP': 'DOWN', 'DOWN': 'UP', 'LEFT': 'RIGHT', 'RIGHT': 'LEFT'\n\t\t};\n\t\tif (nextDirection && oppositeMap[nextDirection] !== direction) {\n\t\t\tdirection = nextDirection;\n\t\t}\n\n\t\t// compute new head\n\t\tlet newHead = [...snake[0]];\n\t\tswitch (direction) {\n\t\t\tcase 'UP': newHead[1]--; break;\n\t\t\tcase 'DOWN': newHead[1]++; break;\n\t\t\tcase 'LEFT': newHead[0]--; break;\n\t\t\tcase 'RIGHT': newHead[0]++; break;\n\t\t\tdefault: break;\n\t\t}\n\n\t\tconst headX = newHead[0];\n\t\tconst headY = newHead[1];\n\t\tconst willEat = (headX === food.x && headY === food.y);\n\n\t\t// Build new snake array\n\t\tlet newSnake = [newHead, ...snake];\n\t\tif (!willEat) {\n\t\t\tnewSnake.pop();   // remove tail if not eating\n\t\t}\n\n\t\t// ---- Collision detection ----\n\t\t// Wall collision\n\t\tif (headX < 0 || headX >= BOARD_SIZE || headY < 0 || headY >= BOARD_SIZE) {\n\t\t\tendGame(false);\n\t\t\tdrawGame();\n\t\t\treturn false;\n\t\t}\n\n\t\t// Self collision: check if the head position appears more than once in newSnake\n\t\tconst headPos = newSnake[0];\n\t\tlet selfCollision = false;\n\t\tfor (let i = 1; i < newSnake.length; i++) {\n\t\t\tif (newSnake[i][0] === headPos[0] && newSnake[i][1] === headPos[1]) {\n\t\t\t\tselfCollision = true;\n\t\t\t\tbreak;\n\t\t\t}\n\t\t}\n\t\tif (selfCollision) {\n\t\t\tendGame(false);\n\t\t\tdrawGame();\n\t\t\treturn false;\n\t\t}\n\n\t\t// Apply new snake\n\t\tsnake = newSnake;\n\n\t\t// Handle food consumption\n\t\tif (willEat) {\n\t\t\tscore++;\n\t\t\tupdateScoreUI();\n\t\t\tconst success = generateRandomFood();\n\t\t\tif (!success) {\n\t\t\t\t// board is completely full → WIN!\n\t\t\t\tendGame(true);\n\t\t\t\tdrawGame();\n\t\t\t\treturn false;\n\t\t\t}\n\t\t}\n\n\t\tdrawGame();\n\t\treturn true;\n\t}\n\n\t// Game tick (called by interval)\n\tfunction gameTick() {\n\t\tif (!gameActive || paused) return;\n\t\tmoveSnake();\n\t\t// additional check if game became inactive due to moveSnake endGame\n\t\tif (!gameActive) {\n\t\t\tstopGameLoop();\n\t\t}\n\t}\n\n\t// ---------- DIRECTION CONTROL (keyboard + buttons) ----------\n\tfunction setDirection(newDir) {\n\t\tif (!gameActive || paused) return;   // no direction changes while paused or game over\n\t\tconst opposite = {\n\t\t\t'UP': 'DOWN', 'DOWN': 'UP', 'LEFT': 'RIGHT', 'RIGHT': 'LEFT'\n\t\t};\n\t\t// prevent 180° flip\n\t\tif (opposite[newDir] !== direction) {\n\t\t\tnextDirection = newDir;\n\t\t}\n\t}\n\n\t// ---------- DRAW EVERYTHING (canvas with pause/gameover overlays) ----------\n\tfunction drawGame() {\n\t\tif (!ctx) return;\n\t\tctx.clearRect(0, 0, 500, 500);\n\n\t\t// draw background grid (soft lines)\n\t\tctx.strokeStyle = '#2b6e4e';\n\t\tctx.lineWidth = 0.6;\n\t\tfor (let i = 0; i <= BOARD_SIZE; i++) {\n\t\t\tctx.beginPath();\n\t\t\tctx.moveTo(i * CELL_SIZE, 0);\n\t\t\tctx.lineTo(i * CELL_SIZE, 500);\n\t\t\tctx.stroke();\n\t\t\tctx.moveTo(0, i * CELL_SIZE);\n\t\t\tctx.lineTo(500, i * CELL_SIZE);\n\t\t\tctx.stroke();\n\t\t}\n\n\t\t// draw food (red apple style)\n\t\tctx.shadowBlur = 0;\n\t\tctx.fillStyle = '#ea5a47';\n\t\tctx.beginPath();\n\t\tconst fx = food.x * CELL_SIZE, fy = food.y * CELL_SIZE;\n\t\tctx.arc(fx + CELL_SIZE / 2, fy + CELL_SIZE / 2, CELL_SIZE * 0.38, 0, Math.PI * 2);\n\t\tctx.fill();\n\t\tctx.fillStyle = '#fff0b0';\n\t\tctx.beginPath();\n\t\tctx.arc(fx + CELL_SIZE * 0.65, fy + CELL_SIZE * 0.35, CELL_SIZE * 0.1, 0, Math.PI * 2);\n\t\tctx.fill();\n\t\tctx.fillStyle = '#5a2e1a';\n\t\tctx.beginPath();\n\t\tctx.moveTo(fx + CELL_SIZE * 0.75, fy + CELL_SIZE * 0.2);\n\t\tctx.lineTo(fx + CELL_SIZE * 0.9, fy + CELL_SIZE * 0.05);\n\t\tctx.lineTo(fx + CELL_SIZE * 0.85, fy + CELL_SIZE * 0.25);\n\t\tctx.fill();\n\n\t\t// draw snake (gradient green)\n\t\tfor (let i = 0; i < snake.length; i++) {\n\t\t\tconst [x, y] = snake[i];\n\t\t\tconst posX = x * CELL_SIZE;\n\t\t\tconst posY = y * CELL_SIZE;\n\t\t\tconst gradient = ctx.createLinearGradient(posX, posY, posX + CELL_SIZE, posY + CELL_SIZE);\n\t\t\tif (i === 0) {\n\t\t\t\tgradient.addColorStop(0, '#6cc24a');\n\t\t\t\tgradient.addColorStop(1, '#3b8f2c');\n\t\t\t} else {\n\t\t\t\tgradient.addColorStop(0, '#4b9e3a');\n\t\t\t\tgradient.addColorStop(1, '#2b7340');\n\t\t\t}\n\t\t\tctx.fillStyle = gradient;\n\t\t\tctx.fillRect(posX + 1, posY + 1, CELL_SIZE - 2, CELL_SIZE - 2);\n\t\t\tctx.fillStyle = '#cdf2b0';\n\t\t\tif (i === 0) {\n\t\t\t\tctx.beginPath();\n\t\t\t\tctx.arc(posX + CELL_SIZE * 0.7, posY + CELL_SIZE * 0.35, CELL_SIZE * 0.12, 0, Math.PI * 2);\n\t\t\t\tctx.fill();\n\t\t\t\tctx.fillStyle = '#1f2e1c';\n\t\t\t\tctx.beginPath();\n\t\t\t\tctx.arc(posX + CELL_SIZE * 0.7, posY + CELL_SIZE * 0.33, CELL_SIZE * 0.06, 0, Math.PI * 2);\n\t\t\t\tctx.fill();\n\t\t\t}\n\t\t}\n\n\t\t// ---- Overlay messages (pause / game over) ----\n\t\tif (!gameActive) {\n\t\t\tctx.fillStyle = 'rgba(0, 0, 0, 0.78)';\n\t\t\tctx.fillRect(0, 0, 500, 500);\n\t\t\tctx.font = `bold ${Math.floor(CELL_SIZE * 1.4)}px \"Courier New\", monospace`;\n\t\t\tctx.fillStyle = winFlag ? '#fed54e' : '#ffaa77';\n\t\t\tctx.shadowBlur = 0;\n\t\t\tctx.textAlign = \"center\";\n\t\t\tconst message = winFlag ? \"✨ YOU WIN! ✨\" : \"☠️ GAME OVER ☠️\";\n\t\t\tctx.fillText(message, 250, 250);\n\t\t\tctx.font = `18px monospace`;\n\t\t\tctx.fillStyle = '#c7e9c0';\n\t\t\tctx.fillText(\"press RESTART\", 250, 340);\n\t\t\tctx.textAlign = \"left\";\n\t\t}\n\t\telse if (paused) {\n\t\t\tctx.fillStyle = 'rgba(10, 20, 8, 0.75)';\n\t\t\tctx.fillRect(0, 0, 500, 500);\n\t\t\tctx.font = `bold ${Math.floor(CELL_SIZE * 1.5)}px \"Courier New\", monospace`;\n\t\t\tctx.fillStyle = '#f5e5a0';\n\t\t\tctx.textAlign = \"center\";\n\t\t\tctx.fillText(\"⏸ PAUSED\", 250, 260);\n\t\t\tctx.font = `14px monospace`;\n\t\t\tctx.fillStyle = '#adf0b2';\n\t\t\tctx.fillText(\"press PAUSE or [P] to resume\", 250, 340);\n\t\t\tctx.textAlign = \"left\";\n\t\t}\n\n\t\t// draw neat border\n\t\tctx.strokeStyle = '#adffa3';\n\t\tctx.lineWidth = 2.5;\n\t\tctx.strokeRect(2, 2, 496, 496);\n\t}\n\n\t// ---------- EVENT HANDLERS ----------\n\tfunction handleKeyDown(e) {\n\t\tconst key = e.key;\n\t\t// prevent arrow keys from scrolling\n\t\tif (key === 'ArrowUp' || key === 'ArrowDown' || key === 'ArrowLeft' || key === 'ArrowRight' ||\n\t\t\tkey === ' ' || key === 'Space' || key === 'p' || key === 'P' || key === 'r' || key === 'R') {\n\t\t\te.preventDefault();\n\t\t}\n\n\t\t// direction controls (only if game active and not paused)\n\t\tif (gameActive && !paused) {\n\t\t\tswitch (key) {\n\t\t\t\tcase 'ArrowUp': setDirection('UP'); break;\n\t\t\t\tcase 'ArrowDown': setDirection('DOWN'); break;\n\t\t\t\tcase 'ArrowLeft': setDirection('LEFT'); break;\n\t\t\t\tcase 'ArrowRight': setDirection('RIGHT'); break;\n\t\t\t\tdefault: break;\n\t\t\t}\n\t\t}\n\n\t\t// Pause toggle: key P or p (works also when game active)\n\t\tif (key === 'p' || key === 'P') {\n\t\t\tif (gameActive) {\n\t\t\t\ttogglePause();\n\t\t\t}\n\t\t}\n\n\t\t// Restart: R key always works, even during game over or paused\n\t\tif (key === 'r' || key === 'R') {\n\t\t\tresetGame();\n\t\t}\n\t}\n\n\t// Buttons control\n\tfunction bindButtons() {\n\t\t// direction buttons\n\t\tdocument.querySelectorAll('[data-dir]').forEach(btn => {\n\t\t\tbtn.addEventListener('click', (e) => {\n\t\t\t\te.preventDefault();\n\t\t\t\tconst dir = btn.getAttribute('data-dir');\n\t\t\t\tif (gameActive && !paused) {\n\t\t\t\t\tsetDirection(dir);\n\t\t\t\t}\n\t\t\t});\n\t\t\t// touch device friendly\n\t\t\tbtn.addEventListener('touchstart', (e) => {\n\t\t\t\te.preventDefault();\n\t\t\t\tconst dir = btn.getAttribute('data-dir');\n\t\t\t\tif (gameActive && !paused) setDirection(dir);\n\t\t\t});\n\t\t});\n\n\t\tconst pauseBtn = document.getElementById('pauseButton');\n\t\tpauseBtn.addEventListener('click', (e) => {\n\t\t\te.preventDefault();\n\t\t\tif (gameActive) togglePause();\n\t\t});\n\t\tpauseBtn.addEventListener('touchstart', (e) => {\n\t\t\te.preventDefault();\n\t\t\tif (gameActive) togglePause();\n\t\t});\n\n\t\tconst restartBtn = document.getElementById('restartButton');\n\t\trestartBtn.addEventListener('click', (e) => {\n\t\t\te.preventDefault();\n\t\t\tresetGame();\n\t\t});\n\t\trestartBtn.addEventListener('touchstart', (e) => {\n\t\t\te.preventDefault();\n\t\t\tresetGame();\n\t\t});\n\t}\n\n\t// ---------- INITIALIZE GAME ----------\n\tfunction init() {\n\t\tbindButtons();\n\t\twindow.addEventListener('keydown', handleKeyDown);\n\t\t// initialize fresh game\n\t\tresetGame();\n\t}\n\n\t// start everything\n\tinit();\n})();\naddEventListener(\"signal\", async function(e) {\n\tif (e.detail == 15) await window.availableAPIs.terminate();\n});"},"buildInfo":{"for":"1629","version":1629,"when":1779970850924,"signer":"moduleSigner","critical":false,"bootO